// Import of required libraries
import { test, expect, getBaseUrl, getValue, newSkyrampPlaywrightPage } from '@skyramp/skyramp';
import { inviteMemberByEmail, signIn } from './skyrampUtils';

const pageTimeout = 15000;

// URL for test requests
const baseUrl = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test.use({
    viewport: { width: 1280, height: 900 },
});

test('testUi', async ({ page }) => {
    test.setTimeout(83000);

    // set default timeout for all locator/page actions in this test
    page.setDefaultTimeout(pageTimeout);
    // Wrap playwright page with Skyramp page
    page = newSkyrampPlaywrightPage(page);

    const pageErrors: string[] = [];
    page.on('pageerror', (error: Error) => pageErrors.push(error.message));

    // Credential(s) read from the environment — never recorded into this file. Set these before running.
    if (process.env.SKYRAMP_UI_PASSWORD === undefined) {
        throw new Error("SKYRAMP_UI_PASSWORD is not set: this test replays a login and needs that credential in the environment");
    }
    const loginPassword = process.env.SKYRAMP_UI_PASSWORD ?? "";

    await page.goto(`${baseUrl}/settings/collection-members`);
    await page.goto(`${baseUrl}/login`);
    await signIn(page, "testbot-admin", loginPassword);
    await page.waitForURL((u) => !u.pathname.startsWith('/login'));
    await page.goto(`${baseUrl}/settings/collection-members`);
    await page.locator('input[placeholder="Invite by email…"]').waitFor({ state: 'visible', timeout: 10000 });
    await expect(page.getByRole("textbox", { name: "Invite by email…" })).toBeVisible();

    const playwrightRequest0: Record<string, any> = {"email": "no-such-user@example.com"};

    // Wait to finish any potential hydration
    await page.waitForTimeout(1500);
    const response0 = await inviteMemberByEmail(page, getValue(playwrightRequest0, "email"));

    // Wait for network activities to finish
    await page.waitForTimeout(3000);

    // The invite is refused because no user holds that address.
    expect(response0.status(), 'the invite request the page sent').toBe(404);
    expect(JSON.parse(await response0.text()).response, 'the reason the backend gave')
        .toBe("User not found.");

    // The page has to surface that rejection rather than swallow it.
    await expect(page.getByText("User not found.")).toBeVisible();
    await expect(page.locator("main p.text-error")).toHaveText("User not found.");
    // A successful invite clears the field; a refused one leaves what was typed.
    await expect(page.getByRole("textbox", { name: "Invite by email…" })).toHaveValue("no-such-user@example.com");

    expect(pageErrors, 'the page raised no script errors').toEqual([]);
});
